<template>
  <div class="lobbies">
    <div
      v-for="lobby in devMode ? devGames : games"
      :key="lobby.id"
      :class="['lobby']"
      :style="{
        background: 'linear-gradient(rgba(31, 31, 31, 0.7),rgba(31, 31, 31, 0.9)),  url(' + lobby.background + ') no-repeat center center',
        backgroundSize: 'cover',
      }"
    >
      <div class="info">
        <div class="lobby-name">{{ lobby.name }}<i v-show="lobby.password" class="fas fa-lock lobby-locked"></i></div>
        <div class="lobby-info">
          <div v-show="lobby.gamemode" class="lobby-gamemode">{{ lobby.gamemode }}</div>
          <div v-show="lobby.description" class="lobby-description">{{ lobby.description }}</div>
          <div class="players players-alt">
            <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span
            ><i class="fas fa-users"></i>
          </div>
        </div>
      </div>
      <div class="players players-main">
        <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span
        ><i class="fas fa-users"></i>
      </div>
      <div class="join">
        <button
          :class="[
            'join-button',
            { current: currentMinigame === lobby.id, full: lobby.players === lobby.maxplayers && currentMinigame !== lobby.id },
          ]"
          @click="joinMinigame(lobby.id, lobby.name, lobby.players, lobby.maxplayers, lobby.password)"
          :disabled="lobby.players === lobby.maxplayers || currentMinigame === lobby.id"
        >
          <div v-if="currentMinigame === lobby.id">Joined</div>
          <div v-else-if="lobby.maxplayers === 0">N/A</div>
          <div v-else-if="lobby.players === lobby.maxplayers">Full</div>
          <div v-else>Join</div>
        </button>
      </div>
    </div>
  </div>
</template>

