<template>
  <div class="tabs">
    <div class="headers">
      <div class="logo">
        <img :src="collapsed ? logoSmall : logoBig" alt="rnc" />
      </div>
      <div v-for="tab in tabTitles" :key="tab.title" class="header">
        <button
          v-wave="{
            color: 'rgb(91, 145, 254)',
          }"
          class="inner"
          :class="{ selected: tab.title === hoverTitle }"
          @click="clickHandle(tab.title)"
          @mouseover="hoverTitle = tab.title"
          @mouseout="hoverTitle = selectedTitle"
        >
          <div class="icon">
            <i :class="['bx', tab.icon]"></i>
          </div>
          <div class="title" v-if="!collapsed">{{ tab.title }}</div>
        </button>
      </div>
      <div class="customTabs">
        <button class="customTab" @click="$emit('toggleStaff')">
          <div class="icon">
            <i v-if="!staff" class="bx bx-user"></i>
            <i v-else class="bx bx-home"></i>
          </div>
          <div class="title">
            <template v-if="!staff">Staff</template
            ><template v-else>Home</template>
          </div>
        </button>
      </div>
    </div>
    <div class="content">
      <transition name="slide" appear>
        <div
          v-if="tabTitles.find(({ title }) => title === selectedTitle).top"
          class="top"
        ></div>
      </transition>
      <div class="bottom max-h-full">
        <slot />
      </div>
    </div>
  </div>
</template>

<script>
import { ref, provide } from "vue";
import $ from "jquery";

export default {
  name: "TabsWrapper",
  props: ["staff", "admin", "collapsed"],
  emits: ["toggleStaff", "collapse"],
  methods: {
    clickHandle(title) {
      this.selectedTitle = title;
    },
    collapse() {
      console.log(`jebo te `);
      $(".tabs_header").toggleClass("collapsed");
      this.$emit("collapse");
    },
  },
  data() {
    return {
      hoverTitle: this.selectedTitle,
      logoBig: require("@/assets/logobig.png"),
      logoSmall: require("@/assets/logo.png"),
      logoURL: `https://cdn.discordapp.com/attachments/890530526509797376/894658481221664848/RNC_COVER_CONCEPT_2.png`,
    };
  },
  setup(props, { slots }) {
    //console.log(slots.default());
    let tabs = slots
      .default()
      .filter((tab) => tab.props)
      .map((tab) => tab.props);
    if (Array.isArray(slots.default()[slots.default().length - 1].children))
      tabs = tabs.concat(
        // prettier-ignore
        slots.default()[slots.default().length - 1].children.map((tab) => tab.props)
      );

    const tabTitles = ref(tabs);

    const selectedTitle = ref(tabTitles.value[1].title);
    //console.log(tabTitles.value);

    provide("selectedTitle", selectedTitle);
    provide("tabTitles", tabTitles);
    return {
      selectedTitle,
      tabTitles,
    };
  },
};
</script>

<style scoped lang="scss">
.tabs {
  height: 100%;
  width: 100%;
  display: flex;

  .logo {
    width: 100%;
    height: 60px;
    display: flex;
    justify-content: center;
    align-items: center;

    img {
      width: 150px;
      height: 30px;
    }
  }

  .headers {
    height: 100%;
    width: 170px;
    min-width: 170px;
    color: $gray-text;
    background: $foreground;
    display: flex;
    flex-direction: column;
    position: relative;

    .customTabs {
      position: absolute;
      width: 100%;
      bottom: 10px;
      padding: 0 10px;

      display: flex;
      justify-content: center;
      align-content: center;

      .customTab {
        background: $gray;
        border-radius: 15px;
        width: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
        height: 50px;
        color: $white-text;
        font-weight: bold;
        font-size: 17px;
        &:hover {
          background: darken($gray, 2%);
        }

        .title {
          display: flex;
          justify-content: flex-start;
          width: 60px;
        }

        .bx {
          width: 20px;
          font-size: 25px;
          display: flex;
          justify-content: center;
          align-content: center;
          margin-right: 5px;
        }
      }
    }

    .selected {
      color: $blue !important;

      &::after {
        bottom: 0px !important;
        height: 50px !important;
        width: 150px !important;
      }
    }

    .header {
      display: grid;
      justify-content: center;
      align-items: center;
      position: relative;
      margin-bottom: 5px;
      border-radius: 15px;

      .inner {
        transition: all 0.4s;
        display: flex;
        justify-content: flex-start;
        align-items: center;
        padding: 10px;
        border-radius: 15px;
        font-size: 17px;
        width: 150px;
        height: 50px;
        font-weight: bold;

        color: #ced6e2a6;

        &::after {
          transition: all 0.4s;
          transition-timing-function: cubic-bezier(0.42, 0, 0, 1.68);
          position: absolute;
          content: "";
          height: 3px;
          bottom: 5px;
          background: rgba($blue, 0.1);
          width: 100px;
          border-radius: 15px;
          left: 50%;
          transform: translate(-50%, 0);
        }

        .icon {
          display: grid;
          justify-content: center;
          align-items: center;
          text-align: center;
          width: 42px;

          .bx {
            font-size: 30px;
          }
        }
      }
    }
  }

  .content {
    width: 100%;
    height: 100%;
    max-width: 100%;
    max-height: 100%;
    display: flex;
    flex-direction: column;

    .top {
      min-height: 60px;
      background: $foreground;
    }

    .bottom {
      min-height: 100%;
      max-height: 100%;
      background: $background;
      border-radius: 15px;
      padding: 10px;
      box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px inset;
      position: relative;
    }
  }
}
</style>
